+      expect(threw).toContain("Cannot tell whether atomaton/issue-12 exists on origin");
+      expect(threw).toContain("Retry the call");
+    } finally {
+      rmSync(root, { recursive: true, force: true, maxRetries: 5 });
+    }
+  });
+});
